func diffLineClass(line string) string {
	switch {
	case strings.HasPrefix(line, "+"):
		return "bg-green-50 px-3 text-green-800"
	case strings.HasPrefix(line, "-"):
		return "bg-red-50 px-3 text-red-800"
	case strings.HasPrefix(line, "@@"):
		return "px-3 text-slate-400"
	default:
		return "px-3 text-slate-600"
	}
}

